// Extract OAuth callback parameters from webhook
const webhookData = $input.first().json;
console.log('Full webhook data:', JSON.stringify(webhookData, null, 2));

const query = webhookData.query || {};
const code = query.code;
const state = query.state;
const error = query.error;

console.log('Extracted code:', code);
console.log('Extracted state:', state);

// Handle OAuth errors
if (error) {
  throw new Error(`OAuth error: ${error} - ${query.error_description || ''}`);
}

// Validate code exists
if (!code) {
  throw new Error('No authorization code received from Google');
}

// IMPORTANT: redirect_uri must EXACTLY match what was used in the initial OAuth request
const redirectUri = 'http://localhost:5678/webhook/oauth-callback';

console.log('Using redirect_uri:', redirectUri);

// Return data for token exchange
return {
  code: code,
  company_name: decodeURIComponent(state || 'Unknown Company'),
  redirect_uri: redirectUri
};

// Log what we're about to send to Google
const data = $input.first().json;

console.log('=== TOKEN EXCHANGE REQUEST ===');
console.log('Code:', data.code);
console.log('Redirect URI:', data.redirect_uri);
console.log('Company Name:', data.company_name);

// Pass through the data unchanged
return data;

// Extract tokens from Google OAuth response
// Handle both wrapped and unwrapped responses
const inputData = $input.first().json;
console.log('=== EXTRACT TOKENS - RAW INPUT ===');
console.log('Type of input:', typeof inputData);
console.log('Input keys:', Object.keys(inputData));
console.log('Full input (first 500 chars):', JSON.stringify(inputData).substring(0, 500));

let tokenResponse = inputData;

// Check if we got a wrapped response (with body, headers, statusCode)
if (tokenResponse.body && typeof tokenResponse.body === 'object') {
  console.log('Got wrapped response, extracting body');
  tokenResponse = tokenResponse.body;
} else if (typeof tokenResponse.body === 'string') {
  console.log('Got string body, parsing...');
  try {
    tokenResponse = JSON.parse(tokenResponse.body);
  } catch (e) {
    console.log('Failed to parse body as JSON:', e.message);
  }
}

console.log('After unwrapping - token response keys:', Object.keys(tokenResponse));

// Check if token exchange failed (error response)
if (tokenResponse.error) {
  throw new Error(`Token exchange failed: ${tokenResponse.error} - ${tokenResponse.error_description || ''}`);
}

// Validate token response
if (!tokenResponse || !tokenResponse.access_token) {
  throw new Error('Failed to get access token. Response: ' + JSON.stringify(tokenResponse));
}

// Get company name from previous node
const previousData = $('Extract OAuth Code').item.json;
const companyName = previousData.company_name || 'Unknown Company';

// Extract token data
const accessToken = tokenResponse.access_token;
const refreshToken = tokenResponse.refresh_token || '';
const expiresIn = tokenResponse.expires_in || 3600;
const scope = tokenResponse.scope || '';

console.log('=== EXTRACTED TOKEN DATA ===');
console.log('Access token length:', accessToken.length);
console.log('Access token preview:', accessToken.substring(0, 30) + '...');
console.log('Refresh token exists:', !!refreshToken);
console.log('Expires in:', expiresIn);
console.log('Scope:', scope);

// Validate access token is not empty
if (!accessToken || accessToken.trim() === '') {
  throw new Error('Access token is empty or invalid');
}

// Generate credential ID
const credentialId = 'google_cred_' + Date.now();

// Return data for next steps
const outputData = {
  company_name: companyName,
  access_token: accessToken,
  refresh_token: refreshToken,
  expires_in: expiresIn,
  scope: scope,
  n8n_credential_id: credentialId
};

console.log('=== OUTPUT DATA ===');
console.log('Output keys:', Object.keys(outputData));
console.log('Output access_token exists:', !!outputData.access_token);

return outputData;

// Debug: Check what data we have before calling Get User Email
const data = $input.first().json;

console.log('=== DEBUG BEFORE GET USER EMAIL ===');
console.log('Full data object:', JSON.stringify(data, null, 2));
console.log('Access token exists:', !!data.access_token);
console.log('Access token length:', data.access_token ? data.access_token.length : 0);
console.log('Access token preview:', data.access_token ? data.access_token.substring(0, 20) + '...' : 'MISSING');
console.log('Company name:', data.company_name);

// Create the full Authorization header value here
const authHeader = 'Bearer ' + data.access_token;
console.log('Authorization header preview:', authHeader.substring(0, 30) + '...');

// Pass through data with the auth header added
return {
  ...data,
  auth_header: authHeader
};

// Get user email from Google userinfo API
let userInfo = $input.first().json;

// Check if we got a wrapped response
if (userInfo.body && typeof userInfo.body === 'object') {
  console.log('Got wrapped response, extracting body');
  userInfo = userInfo.body;
}

// Validate user info
if (!userInfo || !userInfo.email) {
  throw new Error('Failed to get user email. Response: ' + JSON.stringify(userInfo));
}

// Get token data from previous node - using the Extract Tokens node
const tokenData = $('Extract Tokens').item.json;

// Combine all data for backend registration
return {
  company_name: tokenData.company_name,
  email: userInfo.email,
  user_name: userInfo.name || '',
  access_token: tokenData.access_token,
  refresh_token: tokenData.refresh_token,
  n8n_credential_id: tokenData.n8n_credential_id,
  expires_in: tokenData.expires_in,
  scope: tokenData.scope
};

